// ---------------------------------------------------------------------------

/** Active statuses shown on the week calendar */
const ACTIVE_STATUSES = ['in_progress', 'on_hold', 'verified', 'ready'] as const

/**
 * Fetch repairs for a date range (week). Filters by active statuses only.
 *
 * @param from — Inclusive epoch-ms lower bound
 * @param to — Inclusive epoch-ms upper bound
 */
export async function getRepairsForWeek(from: number, to: number): Promise<PaginatedRepairs> {
  const statusIn = ACTIVE_STATUSES.join(',')
  const params = new URLSearchParams()
  params.set('from', String(from))
  params.set('to', String(to))
  params.set('statusIn', statusIn)
  params.set('page', '1')
  params.set('pageSize', '100') // calendar needs all repairs for the week

  const response = await fetch(`/api/repairs?${params.toString()}`)

  if (!response.ok) {
    throw new Error('Failed to fetch repairs for week')
  }

  return response.json()
}

/**
 * useRepairsForWeek — Data hook for the week calendar view.
 *
 * Fetches active repairs for a 7-day range (Mon–Sun) and provides
 * prev/next/today navigation. Returns epoch-ms boundaries so that
 * the UI can distribute repair cards into day columns.
 */

import { useState, useEffect, useCallback } from 'react'
import type { RepairDetailWithCustomer } from '../types.js'
import { getRepairsForWeek } from '../api.js'

// ---------------------------------------------------------------------------
// Week boundary helpers (Mon–Sun, local time)
// ---------------------------------------------------------------------------

/** Get Monday 00:00:00.000 of the week containing `date` */
function mondayOf(date: Date): number {
  const d = new Date(date)
  const day = d.getDay() // 0=Sun, 1=Mon ...
  const diffToMonday = day === 0 ? -6 : 1 - day
  d.setDate(d.getDate() + diffToMonday)
  d.setHours(0, 0, 0, 0)
  return d.getTime()
}

// ---------------------------------------------------------------------------
// Hook interface
// ---------------------------------------------------------------------------

export interface UseRepairsForWeekOptions {
  /** Optional anchor date. Defaults to today. */
  initialDate?: Date
}

export interface UseRepairsForWeekReturn {
  repairs: RepairDetailWithCustomer[]
  weekStart: number // Monday 00:00:00.000 (epoch ms)
  weekEnd: number   // Sunday 23:59:59.999 (epoch ms)
  isLoading: boolean
  error: string | null
  goPrev: () => void
  goNext: () => void
  goToday: () => void
}

/**
 * Fetches repairs for a week range and provides navigation controls.
 */
export function useRepairsForWeek(options?: UseRepairsForWeekOptions): UseRepairsForWeekReturn {
  const anchorDate = options?.initialDate ?? new Date()

  // Track the current Monday to enable prev/next navigation
  const [weekMonday, setWeekMonday] = useState<number>(() => mondayOf(anchorDate))

  const [repairs, setRepairs] = useState<RepairDetailWithCustomer[]>([])
  const [isLoading, setIsLoading] = useState<boolean>(true)
  const [error, setError] = useState<string | null>(null)

  // Compute week boundaries from the current Monday anchor
  const weekStart = weekMonday
  const weekEnd = (() => {
    const sun = new Date(weekMonday)
    sun.setDate(sun.getDate() + 6)
    sun.setHours(23, 59, 59, 999)
    return sun.getTime()
  })()

  // Fetch repairs whenever the week range changes
  useEffect(() => {
    let cancelled = false

    const fetchRepairs = async () => {
      setIsLoading(true)
      setError(null)

      try {
        const result = await getRepairsForWeek(weekStart, weekEnd)
        if (!cancelled) {
          setRepairs(result.repairs)
        }
      } catch (err) {
        if (!cancelled) {
          setError(err instanceof Error ? err.message : 'Failed to fetch repairs')
          setRepairs([])
        }
      } finally {
        if (!cancelled) {
          setIsLoading(false)
        }
      }
    }

    fetchRepairs()

    return () => {
      cancelled = true
    }
  }, [weekStart, weekEnd])

  // Navigation handlers — shift the Monday anchor by ±7 days
  const goPrev = useCallback(() => {
    setWeekMonday((prev) => prev - 7 * 24 * 60 * 60 * 1000)
  }, [])

  const goNext = useCallback(() => {
    setWeekMonday((prev) => prev + 7 * 24 * 60 * 60 * 1000)
  }, [])

  const goToday = useCallback(() => {
    setWeekMonday(mondayOf(new Date()))
  }, [])

  return { repairs, weekStart, weekEnd, isLoading, error, goPrev, goNext, goToday }
}

/**
 * Date anchor utility.
 *
 * Resolves a repair's display date for calendar placement:
 * - Primary: plannedDate (epoch ms)
 * - Fallback: createdAt when plannedDate is null/undefined
 */

export interface DateAnchorInput {
  plannedDate: number | null | undefined
  createdAt: number
}

/**
 * Returns the epoch-ms timestamp to anchor a repair card on the calendar.
 * Uses plannedDate if present; falls back to createdAt.
 */
export function getDateAnchor(input: DateAnchorInput): number {
  return input.plannedDate ?? input.createdAt
}

